// TH14 v1.00b 弹型词表（本卡所需项），自 transcribe/th14/touhou-bullets.ecl 复制。
// 源 type0–23 对应目标同号；常量值是目标行基址，不是源 type 数字。
const TH14_BALL2: int = 432;       // 源 type5
const TH14_BIG_BALL2: int = 656;   // 源 type19

// th14_s3_w02 — TH14 v1.00b Stage 3 道中第 2 波
// 源：st03.ecl.txt::MainSub01(526–533) 入口；依赖 GirlD01(295–317)、GirlD01_at(319–374)、
// MainSub01b(535–547)、MainSub01c(549–561)、Phantom01(832–857)、Phantom01_at(859–880)。
// 源 t=0 = MainSub01 入口；卡开场 OPENING_BUFFER 帧后才起本卡，源无硬时限。
// 省略：普通掉落、anm/音效/震屏等纯表现、章节统计（共用取舍）；死亡回调 Phantom01_at2 见 report。

const TIME_LIMIT: int = 4124;
const OPENING_BUFFER: int = 120;

// 源 EX type2 ANIM a=1：出生时 position -= 4*velocity（出生退位移按共用口径保留）。
xformdef PARENT_DIE {
    wait(120);      // 源 EX index3 WAIT(120)：游标停 120 帧后继续
    set_life(1);    // 源 SHOOT_DATA c=1：子环发出后删除母弹
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

// 源 MainSub01：先起两个侧流，再创建 GirlD01(0,-48,hp1200,score1000,item1)，wait(120) 后返回。
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn side_left();      // 源 @MainSub01b() async
    spawn side_right();     // 源 @MainSub01c() async
    _ = spawn_enemy(0fx, -48fx, 1200, 0, 1000, 0, girl_d01);
}

// 源 MainSub01b：wait(300)、13 只 Phantom01，x=-192，y=64+RANDF*128，每 160 帧。
async sub side_left() {
    wait(300);
    for i in 0..13 {
        var ly: fx = 64fx + (rand(32768) as fx) / 32768 * 128fx;   // 源 %RANDF
        _ = spawn_enemy(-192fx, ly, 130, 0, 1000, 0, phantom01(1));
        wait(160);
    }
}

// 源 MainSub01c：wait(240)、enmCreateM（子镜像位1）x=+192，其余同 b。
async sub side_right() {
    wait(240);
    for i in 0..13 {
        var ry: fx = 64fx + (rand(32768) as fx) / 32768 * 128fx;   // 源 %RANDF
        _ = spawn_enemy(192fx, ry, 130, 0, 1000, 0, phantom01(-1));
        wait(160);
    }
}

// 源 Phantom01：框、!HL 发弹线程、ABS 平移 + REL 圆周（mirror 作用于 moveVel 结果）。
async sub phantom01(dir: int) {
    set_invuln(65535);
    set_hurtbox(14fx);      // 源 setHurtbox(28,28)：圆形分支取第一值×0.5
    set_hitbox(8fx);        // 源 setHitbox(16,16)
    if global(GVAR_RANK) >= RANK_HARD { spawn phantom01_at(); }   // 源 !HL 执行门
    // 源 moveVel(0,1)；moveCircleRel(%RANDRAD, 0.017453292f, 0, 0) 后
    // moveCircleRelTime(80, 0, ω保留, 16, 0)：相位随机、1°/帧、半径 0→16。
    var phase: int = rand(65536) - 32768;    // %RANDRAD 初相（raw BAM）
    var t: int = 0;
    loop {
        var t1: int = t + 1;
        var r0: fx = 16fx;
        var r1: fx = 16fx;
        if t <= 80 { r0 = 16fx * (t as fx) / 80fx; }
        if t1 <= 80 { r1 = 16fx * (t1 as fx) / 80fx; }
        var th0: angle = (phase + t * 182) as angle;    // ω = 1°/帧
        var th1: angle = (phase + t1 * 182) as angle;
        var dx: fx = (dir as fx) + r1 * cos(th1) - r0 * cos(th0);
        var dy: fx = r1 * sin(th1) - r0 * sin(th0);
        move_vel_xy(0, dx, dy, EASE_LINEAR);
        t = t + 1;
        wait(1);
    }
}

// 源 Phantom01_at：配置一次后连发；单发自机狙 speed 2.0，sprite 5/6，ANIM 退位移 4*2.0=8px。
async sub phantom01_at() {
    var rank: int = global(GVAR_RANK);
    // 源 diffWait(60+RAND%180, 60+RAND%40, 60+RAND%40, 40+RAND%40)：四档实参均压栈，按序各抽一次。
    var w_e: int = 60 + rand(180);
    var w_n: int = 60 + rand(40);
    var w_h: int = 60 + rand(40);
    var w_l: int = 40 + rand(40);
    var first: int = w_l;
    if rank == RANK_HARD { first = w_h; }
    else if rank == RANK_NORMAL { first = w_n; }
    else if rank == RANK_EASY { first = w_e; }
    wait(first);
    phantom_shot();
    // 源 diffI($A, 0, 1, 4, 8)
    var rounds: int = 0;
    if rank == RANK_HARD { rounds = 4; }
    else if rank == RANK_LUNATIC { rounds = 8; }
    for k in 0..rounds {
        // 源 diffWait(30+RAND%40, 30+RAND%40, 60+RAND%20, 60+RAND%20)
        var w_e2: int = 30 + rand(40);
        var w_n2: int = 30 + rand(40);
        var w_h2: int = 60 + rand(20);
        var w_l2: int = 60 + rand(20);
        var pace: int = w_l2;
        if rank == RANK_HARD { pace = w_h2; }
        wait(pace);
        phantom_shot();
    }
}

sub phantom_shot() {
    var aim: angle = aim_player();
    _ = fire(TH14_BALL2, 6,
             $self_x - 8fx * cos(aim), $self_y - 8fx * sin(aim),   // 4*2.0 出生退位移
             2fx, aim, none, none);
}

// 源 GirlD01：框、ABS 平移（2.7 朝下二次减速到 0；120 帧后二次加速到 1）、发弹线程。
async sub girl_d01() {
    set_invuln(65535);
    set_hurtbox(16fx);      // 源 setHurtbox(32,32)
    set_hitbox(12fx);       // 源 setHitbox(24,24)
    move_vel(0, 90deg, 2.7fx, EASE_LINEAR);     // 源 moveVel(1.5707964f, 2.7f)
    move_speed(60, 0fx, EASE_QUAD_IN);          // 源 moveSpeedTime(60, 1, 0.0f)
    spawn girl_d01_at();
    wait(120);
    move_speed(80, 1fx, EASE_QUAD_IN);          // 源 moveSpeedTime(80, 1, 1.0f)
    wait(60);
    loop { wait(1000); }
}

// 源 GirlD01_at：慢速(0.2) 两路扇形母弹；每发母弹的 EX 在 120 帧后于母弹位置爆出 8 路环。
async sub girl_d01_at() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    // 源 diffI($B,2,4,6,8)；每轮 wait 40/20/13/10；SHOOT 首速 2.0/2.0/2.5/3.0；层 2/2/3/3
    var rounds: int = 2;
    var pace: int = 40;
    var sp0: fx = 2fx;
    var layers: int = 2;
    if rank == RANK_NORMAL { rounds = 4; pace = 20; }
    else if rank == RANK_HARD { rounds = 6; pace = 13; sp0 = 2.5fx; layers = 3; }
    else if rank == RANK_LUNATIC { rounds = 8; pace = 10; sp0 = 3fx; layers = 3; }
    var spread: int = 16384;    // %A = 1.570796f
    for k in 0..rounds {
        var rot: int = rand(65536) - 32768;     // 源 SHOOT r=%RANDRAD（配置时抽一次）
        var drift: int = rand(65536) - 32768;   // 源 SHOOT s=%RANDRAD
        var half: int = spread / 2;
        var a0: int = 16384 + half;             // 源 etAngle(0, π/2, %A) 两路扇形
        var a1: int = 16384 - half;
        var px: fx = $self_x - 0.8fx * cos(a0 as angle);   // ANIM 退位移 4*0.2
        var py: fx = $self_y - 0.8fx * sin(a0 as angle);
        var qx: fx = $self_x - 0.8fx * cos(a1 as angle);
        var qy: fx = $self_y - 0.8fx * sin(a1 as angle);
        _ = fire(TH14_BIG_BALL2, 3, px, py, 0.2fx, a0 as angle, PARENT_DIE, none);
        _ = fire(TH14_BIG_BALL2, 3, qx, qy, 0.2fx, a1 as angle, PARENT_DIE, none);
        spawn parent_split(px, py, a0 as angle, a1 as angle, rot, drift, layers, sp0);
        spread = spread - 2731;                 // 源 %A -= 0.261799f（15°）
        wait(pace);
    }
}

// 源 EX index4 SHOOT / index5 SHOOT_DATA：aim3 固定方向环 8 路 × layers，
// 层速 sp0→0.9，每颗角 rot + 2πi/8 + q*drift，sprite 5/color 6，子环从母弹当前位置发出。
async sub parent_split(sx: fx, sy: fx, a0: angle, a1: angle, rot: int, drift: int, layers: int, sp0: fx) {
    wait(119);                          // 母弹次帧首跑；源 WAIT(120) 于出生后 120 帧续跑
    var bx: fx = sx + 24fx * cos(a0);   // 母弹 120 帧 × 0.2px/帧
    var by: fx = sy + 24fx * sin(a0);
    burst(bx, by, rot, drift, layers, sp0);
    var cx: fx = sx + 24fx * cos(a1);
    var cy: fx = sy + 24fx * sin(a1);
    burst(cx, cy, rot, drift, layers, sp0);
}

sub burst(x0: fx, y0: fx, rot: int, drift: int, layers: int, sp0: fx) {
    for q in 0..layers {
        var v: fx = sp0;
        if layers > 1 { v = sp0 + (0.9fx - sp0) * (q as fx) / ((layers - 1) as fx); }
        for i in 0..8 {
            var ang: int = rot + i * 8192 + q * drift;
            var back: fx = 4fx * v;     // ANIM 出生退位移
            _ = fire(TH14_BALL2, 6,
                     x0 - back * cos(ang as angle), y0 - back * sin(ang as angle),
                     v, ang as angle, none, none);
        }
    }
}
